static void adventure_double(float x, float y)
{
    if (gesture.kind != SCREEN_ADVENTURE || gesture.ui || gesture.aiming ||
        !isfinite(x) || !isfinite(y) || x < 0 || y < 0 || x > 32767 || y > 32767 ||
        !same_screen() || target_armed() || !ui_idle()) return;
    uint32_t screen = gesture.screen;
    if (read32(screen) != 0x00DD800Cu || !void_dispatch_find(0x0057D870u) ||
        ui_pick(screen, x, y) || !same_screen() || target_armed() || !ui_idle()) return;
    if (!scratch) scratch = void_galloc(512);
    uint32_t argument = scratch + 320;
    if (!scratch || !void_vm_writable(argument, 40)) return;
    memset((void *)ADDR(argument), 0, 40);
    MEM32(argument + 0x24) = ((uint32_t)x & 0x7FFFu) | (((uint32_t)y & 0x7FFFu) << 15);
    /* The original handler converts this raw point once and owns this edition's hero/ghost/town policy. */
    publish_point(x, y);
    if (!same_screen() || target_armed()) return;
    void_call_guest_this(0x0057D870u, screen, 1, &argument);
    if (!same_screen()) { gesture.active = 0; publish_point(-1, -1); }
}

